import { FormId, VerbGroup } from './verb-forms';

export interface VerbEntry {
  /** Dictionary form; kanji are followed by their reading in brackets: 食[た]べる */
  word: string;
  group: VerbGroup;
  meaning: string;
  /** Forms that break the group's rules (written in hiragana) */
  exceptions?: Partial<Record<FormId, string>>;
  /** Extra explanation shown when the player answers wrong */
  note?: string;
}

